import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_01_package_boundary.png",i="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_02_lifecycle_interfaces.png",n="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_03_plan_transform_lookahead.png",s="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_04_control_state_machine.png",c="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_05_velocity_constraints.png",p="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_06_collision_results.png",v=JSON.parse('{"title":"前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流","description":"Regulated Pure Pursuit 可译为“受约束纯追踪”。它不只是追逐前视点，而是在 Pure Pursuit 几何控制前后加入路径裁剪、速度调节、旋转接管和 footprint 碰撞预测，把一条全局 Path 变成可执行的局部速度。","frontmatter":{"title":"前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流","description":"Regulated Pure Pursuit 可译为“受约束纯追踪”。它不只是追逐前视点，而是在 Pure Pursuit 几何控制前后加入路径裁剪、速度调节、旋转接管和 footprint 碰撞预测，把一条全局 Path 变成可执行的局部速度。","date":"2026-07-21","section":"三 · 局部控制与速度生成","readingTime":6,"source":"2026-07-21/nav2_regulated_pure_pursuit_controller_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-21/nav2_rpp_01_package_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-pure-pursuit-controller-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流"}],["meta",{"property":"og:description","content":"Regulated Pure Pursuit 可译为“受约束纯追踪”。它不只是追逐前视点，而是在 Pure Pursuit 几何控制前后加入路径裁剪、速度调节、旋转接管和 footprint 碰撞预测，把一条全局 Path 变成可执行的局部速度。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-pure-pursuit-controller-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_01_package_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-21"}],["meta",{"name":"twitter:title","content":"前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流"}],["meta",{"name":"twitter:description","content":"Regulated Pure Pursuit 可译为“受约束纯追踪”。它不只是追逐前视点，而是在 Pure Pursuit 几何控制前后加入路径裁剪、速度调节、旋转接管和 footprint 碰撞预测，把一条全局 Path 变成可执行的局部速度。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rpp_01_package_boundary.png"}]],"prev":{"text":"一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流","link":"/nav2/nav2-mppi-controller-full-dataflow"},"next":{"text":"别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流","link":"/nav2/nav2-rotation-shim-controller-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-regulated-pure-pursuit-controller-full-dataflow.md","filePath":"nav2/nav2-regulated-pure-pursuit-controller-full-dataflow.md","lastUpdated":null}'),d={name:"nav2/nav2-regulated-pure-pursuit-controller-full-dataflow.md"};function h(u,a,_,P,m,f){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="前方放一根-胡萝卜-机器人就会转弯-拆解-nav2-rpp-全调用、状态与数据流" tabindex="-1">前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流 <a class="header-anchor" href="#前方放一根-胡萝卜-机器人就会转弯-拆解-nav2-rpp-全调用、状态与数据流" aria-label="Permalink to &quot;前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流&quot;">​</a></h1><p>Regulated Pure Pursuit 可译为“受约束纯追踪”。它不只是追逐前视点，而是在 Pure Pursuit 几何控制前后加入路径裁剪、速度调节、旋转接管和 footprint 碰撞预测，把一条全局 Path 变成可执行的局部速度。</p><h2 id="一、rpp-是-controller-插件" tabindex="-1">一、RPP 是 Controller 插件 <a class="header-anchor" href="#一、rpp-是-controller-插件" aria-label="Permalink to &quot;一、RPP 是 Controller 插件&quot;">​</a></h2><h3 id="_1-1-ros-接口由-controller-server-管理" tabindex="-1">1.1 ROS 接口由 Controller Server 管理 <a class="header-anchor" href="#_1-1-ros-接口由-controller-server-管理" aria-label="Permalink to &quot;1.1 ROS 接口由 Controller Server 管理&quot;">​</a></h3><p>RPP 不创建独立节点。Controller Server 接收 FollowPath Action，持有 Local Costmap、TF、Odometry、ProgressChecker、GoalChecker 和 <code>cmd_vel</code> Publisher，再通过 <code>setPlan()</code>、<code>computeVelocityCommands()</code> 与 <code>setSpeedLimit()</code> 调用 RPP。</p><p>插件输入是本周期 Pose、当前 Twist、GoalChecker，以及内部缓存的 Path、Costmap 和参数；输出是 <code>TwistStamped</code>。Action Feedback、Result、失败容忍和最终零速不属于 RPP。</p><h3 id="_1-2-最终速度受多层约束" tabindex="-1">1.2 最终速度受多层约束 <a class="header-anchor" href="#_1-2-最终速度受多层约束" aria-label="Permalink to &quot;1.2 最终速度受多层约束&quot;">​</a></h3><p>RPP 内部决定曲率、目标速度、近障碍降速和碰撞安全；speed limit 修改期望线速度；Controller Server 处理异常；下游 Velocity Smoother 再限制速度、加减速度、死区和超时。</p><p><img src="'+l+'" alt="RPP 包边界与输入输出"></p><h2 id="二、lifecycle-与持久状态" tabindex="-1">二、Lifecycle 与持久状态 <a class="header-anchor" href="#二、lifecycle-与持久状态" aria-label="Permalink to &quot;二、Lifecycle 与持久状态&quot;">​</a></h2><h3 id="_2-1-configure-创建运行资源" tabindex="-1">2.1 configure 创建运行资源 <a class="header-anchor" href="#_2-1-configure-创建运行资源" aria-label="Permalink to &quot;2.1 configure 创建运行资源&quot;">​</a></h3><p>configure 读取参数并由 <code>controller_frequency</code> 派生控制周期，创建 Path、carrot 与碰撞弧三个 Lifecycle Publisher，建立 FootprintCollisionChecker，并保存基础期望速度 <code>base_desired_linear_vel_</code>。</p><p><code>activate()</code> 激活 Publisher 和动态参数回调；<code>deactivate()</code> 关闭运行期入口；<code>cleanup()</code> 释放资源。</p><h3 id="_2-2-控制周期不是完全无状态" tabindex="-1">2.2 控制周期不是完全无状态 <a class="header-anchor" href="#_2-2-控制周期不是完全无状态" aria-label="Permalink to &quot;2.2 控制周期不是完全无状态&quot;">​</a></h3><ul><li><code>global_plan_</code> 保存尚未走完的路径。</li><li><code>desired_linear_vel_</code> 保存当前 speed limit 后的速度。</li><li><code>goal_dist_tol_</code> 来自当前 GoalChecker。</li><li>参数 mutex 与 Costmap mutex 保护共享数据。</li></ul><p><img src="'+i+`" alt="RPP Lifecycle 与接口状态"></p><h2 id="三、全局-path-怎样变成-carrot" tabindex="-1">三、全局 Path 怎样变成 carrot <a class="header-anchor" href="#三、全局-path-怎样变成-carrot" aria-label="Permalink to &quot;三、全局 Path 怎样变成 carrot&quot;">​</a></h2><h3 id="_3-1-路径先裁剪再变换" tabindex="-1">3.1 路径先裁剪再变换 <a class="header-anchor" href="#_3-1-路径先裁剪再变换" aria-label="Permalink to &quot;3.1 路径先裁剪再变换&quot;">​</a></h3><p>RPP 把机器人 Pose 变换到 Path frame，在有限前缀中寻找最近点，再按 Local Costmap 最大半边截取前方 Path。截取结果逐点变换到 base frame，机器人身后的旧前缀从 <code>global_plan_</code> 中永久删除。</p><h3 id="_3-2-前视距离可以随速度变化" tabindex="-1">3.2 前视距离可以随速度变化 <a class="header-anchor" href="#_3-2-前视距离可以随速度变化" aria-label="Permalink to &quot;3.2 前视距离可以随速度变化&quot;">​</a></h3><p>固定模式直接使用 <code>lookahead_dist</code>。速度缩放模式使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lookahead = clamp(|current_vx| × lookahead_time,</span></span>
<span class="line"><span>                  min_lookahead_dist,</span></span>
<span class="line"><span>                  max_lookahead_dist)</span></span></code></pre></div><p>允许倒车时，路径向量方向反转的位置被识别为 cusp，前视距离不能跨过该点。启用插值后，carrot 会精确落在路径线段与前视圆的交点上。</p><p><img src="`+n+`" alt="全局 Path 到局部 carrot"></p><h2 id="四、pure-pursuit-与三分支控制" tabindex="-1">四、Pure Pursuit 与三分支控制 <a class="header-anchor" href="#四、pure-pursuit-与三分支控制" aria-label="Permalink to &quot;四、Pure Pursuit 与三分支控制&quot;">​</a></h2><h3 id="_4-1-几何核心只有一个公式" tabindex="-1">4.1 几何核心只有一个公式 <a class="header-anchor" href="#_4-1-几何核心只有一个公式" aria-label="Permalink to &quot;4.1 几何核心只有一个公式&quot;">​</a></h3><p>carrot 位于 base frame，坐标为 <code>(x, y)</code>，曲率为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curvature = 2y / (x² + y²)</span></span>
<span class="line"><span>angular_velocity = linear_velocity × curvature</span></span></code></pre></div><p>横向偏移越大、前视距离越短，转弯越急。</p><h3 id="_4-2-控制分支有明确优先级" tabindex="-1">4.2 控制分支有明确优先级 <a class="header-anchor" href="#_4-2-控制分支有明确优先级" aria-label="Permalink to &quot;4.2 控制分支有明确优先级&quot;">​</a></h3><p>进入目标 XY 容差后，若启用末端朝向控制，RPP 先原地对齐目标 yaw；否则当 carrot 方位角过大时原地对齐路径；其余情况才执行正常 Pure Pursuit。</p><p>三条分支都要经过碰撞预测，安全后才返回统一 <code>TwistStamped</code>。</p><p><img src="`+s+'" alt="RPP 三分支控制状态机"></p><h2 id="五、线速度如何被逐层调节" tabindex="-1">五、线速度如何被逐层调节 <a class="header-anchor" href="#五、线速度如何被逐层调节" aria-label="Permalink to &quot;五、线速度如何被逐层调节&quot;">​</a></h2><h3 id="_5-1-曲率约束给急弯降速" tabindex="-1">5.1 曲率约束给急弯降速 <a class="header-anchor" href="#_5-1-曲率约束给急弯降速" aria-label="Permalink to &quot;5.1 曲率约束给急弯降速&quot;">​</a></h3><p>当曲率半径小于 <code>regulated_linear_scaling_min_radius</code> 时，线速度按半径比例降低，并受 <code>regulated_linear_scaling_min_speed</code> 保护。</p><h3 id="_5-2-costmap-代价反解障碍距离" tabindex="-1">5.2 Costmap 代价反解障碍距离 <a class="header-anchor" href="#_5-2-costmap-代价反解障碍距离" aria-label="Permalink to &quot;5.2 Costmap 代价反解障碍距离&quot;">​</a></h3><p>RPP 读取机器人当前位置的 Inflation 代价，反向估计到障碍物的距离。进入 <code>cost_scaling_dist</code> 后继续降低速度。这里的 <code>inflation_cost_scaling_factor</code> 必须与 Costmap InflationLayer 一致，否则反解距离失真。</p><h3 id="_5-3-接近目标继续减速" tabindex="-1">5.3 接近目标继续减速 <a class="header-anchor" href="#_5-3-接近目标继续减速" aria-label="Permalink to &quot;5.3 接近目标继续减速&quot;">​</a></h3><p>局部 Path 的剩余积分长度不足 <code>approach_velocity_scaling_dist</code> 时，RPP 根据终点欧氏距离缩放速度，并保证不低于 <code>min_approach_linear_velocity</code>。</p><p>曲率速度与 Costmap 速度取较小值，再应用目标接近缩放、speed limit 和期望速度上限。下游 Velocity Smoother 仍会二次约束，所以 <code>desired_linear_vel</code> 不是最终底盘速度。</p><p><img src="'+c+'" alt="RPP 速度约束链"></p><h2 id="六、原地旋转与倒车" tabindex="-1">六、原地旋转与倒车 <a class="header-anchor" href="#六、原地旋转与倒车" aria-label="Permalink to &quot;六、原地旋转与倒车&quot;">​</a></h2><h3 id="_6-1-旋转角速度受两类边界" tabindex="-1">6.1 旋转角速度受两类边界 <a class="header-anchor" href="#_6-1-旋转角速度受两类边界" aria-label="Permalink to &quot;6.1 旋转角速度受两类边界&quot;">​</a></h3><p>目标角速度由航向误差符号决定。当前 Odometry <code>wz</code> 与 <code>max_angular_accel × dt</code> 形成单周期可达窗口；剩余角度又通过制动公式限制最大角速度，减少过冲。</p><h3 id="_6-2-倒车由路径几何决定" tabindex="-1">6.2 倒车由路径几何决定 <a class="header-anchor" href="#_6-2-倒车由路径几何决定" aria-label="Permalink to &quot;6.2 倒车由路径几何决定&quot;">​</a></h3><p>启用 <code>allow_reversing</code> 后，carrot 的 <code>x</code> 符号决定前进或倒车，cusp 来自相邻路径向量点积而不是 Pose orientation。倒车仍经过曲率、代价、目标和碰撞约束，并与旋转接管互斥。</p><h2 id="七、footprint-怎样预测未来碰撞" tabindex="-1">七、Footprint 怎样预测未来碰撞 <a class="header-anchor" href="#七、footprint-怎样预测未来碰撞" aria-label="Permalink to &quot;七、Footprint 怎样预测未来碰撞&quot;">​</a></h2><h3 id="_7-1-当前姿态先检查" tabindex="-1">7.1 当前姿态先检查 <a class="header-anchor" href="#_7-1-当前姿态先检查" aria-label="Permalink to &quot;7.1 当前姿态先检查&quot;">​</a></h3><p>算法先查询当前 footprint。若已经碰撞，立即抛出 PlannerException。</p><h3 id="_7-2-沿候选-twist-前推" tabindex="-1">7.2 沿候选 Twist 前推 <a class="header-anchor" href="#_7-2-沿候选-twist-前推" aria-label="Permalink to &quot;7.2 沿候选 Twist 前推&quot;">​</a></h3><p>平移时按 Costmap 分辨率选择步长，纯旋转使用独立角度步长，再用单轮车模型推进未来姿态。预测范围受 <code>max_allowed_time_to_collision_up_to_carrot</code> 和 carrot 距离共同限制。</p><p>每个姿态检查完整 footprint，并发布 <code>lookahead_collision_arc</code>。本地实现把 Costmap 外预测点视为无碰撞；允许跟踪未知区时，<code>NO_INFORMATION</code> 也可视为安全，这两个边界必须在实车上额外验证。</p><p><img src="'+p+`" alt="RPP 碰撞预测与结果分支"></p><h2 id="八、异常与动态控制面" tabindex="-1">八、异常与动态控制面 <a class="header-anchor" href="#八、异常与动态控制面" aria-label="Permalink to &quot;八、异常与动态控制面&quot;">​</a></h2><h3 id="_8-1-异常由-controller-server-汇总" tabindex="-1">8.1 异常由 Controller Server 汇总 <a class="header-anchor" href="#_8-1-异常由-controller-server-汇总" aria-label="Permalink to &quot;8.1 异常由 Controller Server 汇总&quot;">​</a></h3><p>空 Path、TF 失败和预测碰撞都会向上抛。Controller Server 在 <code>failure_tolerance</code> 内暂时发布零速，持续失败才终止 FollowPath；GoalChecker 决定最终成功。</p><h3 id="_8-2-动态参数并非全部覆盖" tabindex="-1">8.2 动态参数并非全部覆盖 <a class="header-anchor" href="#_8-2-动态参数并非全部覆盖" aria-label="Permalink to &quot;8.2 动态参数并非全部覆盖&quot;">​</a></h3><p>本地回调支持主要速度、前视、旋转和调节开关，但声明过的参数不一定都能动态更新。<code>setSpeedLimit()</code> 也没有取得 RPP 本地 mutex，运行期高频改参应谨慎。</p><h2 id="九、调参与排障" tabindex="-1">九、调参与排障 <a class="header-anchor" href="#九、调参与排障" aria-label="Permalink to &quot;九、调参与排障&quot;">​</a></h2><h3 id="_9-1-不要孤立调整前视距离" tabindex="-1">9.1 不要孤立调整前视距离 <a class="header-anchor" href="#_9-1-不要孤立调整前视距离" aria-label="Permalink to &quot;9.1 不要孤立调整前视距离&quot;">​</a></h3><p>前视过短会放大路径噪声，过长会切弯。应同时观察 transformed plan、carrot、曲率和控制频率。</p><h3 id="_9-2-inflation-参数必须配套" tabindex="-1">9.2 Inflation 参数必须配套 <a class="header-anchor" href="#_9-2-inflation-参数必须配套" aria-label="Permalink to &quot;9.2 Inflation 参数必须配套&quot;">​</a></h3><p>机器人贴障碍或异常降速时，同时核对 Local Costmap 代价、RPP cost scaling 参数与 footprint，不能只增大某个权重。</p><h3 id="_9-3-三条观测链足够定位" tabindex="-1">9.3 三条观测链足够定位 <a class="header-anchor" href="#_9-3-三条观测链足够定位" aria-label="Permalink to &quot;9.3 三条观测链足够定位&quot;">​</a></h3><ul><li>路径链：原始 Path、裁剪 Path、TF 与 cusp。</li><li>速度链：carrot、曲率、Costmap 代价、speed limit 与 smoother。</li><li>安全链：footprint、碰撞弧、未知区和 Costmap 边界。</li></ul><h2 id="十、总结与参考" tabindex="-1">十、总结与参考 <a class="header-anchor" href="#十、总结与参考" aria-label="Permalink to &quot;十、总结与参考&quot;">​</a></h2><h3 id="_10-1-完整控制数据链" tabindex="-1">10.1 完整控制数据链 <a class="header-anchor" href="#_10-1-完整控制数据链" aria-label="Permalink to &quot;10.1 完整控制数据链&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FollowPath → 局部 Path → carrot → 曲率／旋转</span></span>
<span class="line"><span>→ 曲率＋Costmap＋终点速度调节</span></span>
<span class="line"><span>→ footprint 碰撞预测 → TwistStamped</span></span>
<span class="line"><span>→ Controller Server → Velocity Smoother → cmd_vel</span></span></code></pre></div><p>“追胡萝卜”只是几何核心，真正的工程能力来自它周围的路径状态、速度约束和碰撞状态。</p><h3 id="_10-2-官方参考" tabindex="-1">10.2 官方参考 <a class="header-anchor" href="#_10-2-官方参考" aria-label="Permalink to &quot;10.2 官方参考&quot;">​</a></h3><p><a href="https://docs.nav2.org/configuration/packages/configuring-regulated-pp.html" target="_blank" rel="noreferrer">Nav2 Regulated Pure Pursuit 配置</a></p><p><a href="https://github.com/ros-navigation/navigation2/tree/main/nav2_regulated_pure_pursuit_controller" target="_blank" rel="noreferrer">Navigation2 RPP 源码</a></p>`,73)])])}const g=e(d,[["render",h]]);export{v as __pageData,g as default};
